/* Decode the request of n bytes at req, which came on ch, call its handler,
 * encode the reply into rep (EDU_REP_MAX bytes) and the handles it carries
 * into rhs (IDL_REP_HANDLES slots; *rhn of them). Returns the reply's
 * length: 0 means no reply (the request has no txid, or a `later`
 * handler answers it itself). No I/O; the caller sends the reply with the
 * handles, or closes them if it can't. */
static inline uint32_t edu_dispatch_on(handle_t ch, const struct edu_ops *ops, void *ctx,
                                       const void *req, uint32_t n, void *rep, handle_t *rhs,
                                       uint32_t *rhn)
{
    struct idl_rep_hdr *idl_h = (struct idl_rep_hdr *)rep;
    *rhn = 0;
    (void)rhs;
    (void)ch;
    if (n < sizeof(uint32_t))
        return 0;
    idl_h->txid = ((const struct idl_req_hdr *)req)->txid;
    idl_h->status = ERR_INVALID_ARGS;
    if (n < sizeof(struct idl_req_hdr))
        return sizeof(*idl_h);
    switch (((const struct idl_req_hdr *)req)->ordinal) {
    case EDU_FACTORIAL: {
        const struct edu_factorial_req *idl_q = (const struct edu_factorial_req *)req;
        struct edu_factorial_rep *idl_r = (struct edu_factorial_rep *)rep;
        uint32_t out_result = 0;
        if (n != sizeof(*idl_q))
            return sizeof(*idl_h);
        if (!ops->factorial) {
            idl_h->status = ERR_NOT_SUPPORTED;
            return sizeof(*idl_h);
        }
        status_t idl_st = ops->factorial(ctx, idl_q->n, &out_result);
        idl_h->status = idl_st > 0 ? ERR_INTERNAL : idl_st;
        if (idl_h->status != OK)
            return sizeof(*idl_h);
        idl_r->result = out_result;
        return sizeof(*idl_r);
    }
    case EDU_DMA_ROUNDTRIP: {
        const struct edu_dma_roundtrip_req *idl_q = (const struct edu_dma_roundtrip_req *)req;
        struct edu_dma_roundtrip_rep *idl_r = (struct edu_dma_roundtrip_rep *)rep;
        (void)idl_r;
        if (n != sizeof(*idl_q))
            return sizeof(*idl_h);
        if (!ops->dma_roundtrip) {
            idl_h->status = ERR_NOT_SUPPORTED;
            return sizeof(*idl_h);
        }
        status_t idl_st = ops->dma_roundtrip(ctx, idl_q->len);
        idl_h->status = idl_st > 0 ? ERR_INTERNAL : idl_st;
        if (idl_h->status != OK)
            return sizeof(*idl_h);
        return sizeof(*idl_r);
    }
    case EDU_RAISE_IRQ: {
        const struct edu_raise_irq_req *idl_q = (const struct edu_raise_irq_req *)req;
        struct edu_raise_irq_rep *idl_r = (struct edu_raise_irq_rep *)rep;
        uint64_t out_latency_ns = 0;
        if (n != sizeof(*idl_q))
            return sizeof(*idl_h);
        if (!ops->raise_irq) {
            idl_h->status = ERR_NOT_SUPPORTED;
            return sizeof(*idl_h);
        }
        status_t idl_st = ops->raise_irq(ctx, &out_latency_ns);
        idl_h->status = idl_st > 0 ? ERR_INTERNAL : idl_st;
        if (idl_h->status != OK)
            return sizeof(*idl_h);
        idl_r->latency_ns = out_latency_ns;
        return sizeof(*idl_r);
    }
    case EDU_DMA_START: {
        const struct edu_dma_start_req *idl_q = (const struct edu_dma_start_req *)req;
        struct edu_dma_start_rep *idl_r = (struct edu_dma_start_rep *)rep;
        uint64_t out_device_addr = 0;
        if (n != sizeof(*idl_q))
            return sizeof(*idl_h);
        if (!ops->dma_start) {
            idl_h->status = ERR_NOT_SUPPORTED;
            return sizeof(*idl_h);
        }
        status_t idl_st = ops->dma_start(ctx, idl_q->len, &out_device_addr);
        idl_h->status = idl_st > 0 ? ERR_INTERNAL : idl_st;
        if (idl_h->status != OK)
            return sizeof(*idl_h);
        idl_r->device_addr = out_device_addr;
        return sizeof(*idl_r);
    }
    }
    idl_h->status = ERR_NOT_SUPPORTED;
    return sizeof(*idl_h);
}

/* edu_dispatch_on without the channel (the protocol has no `later` method). */
static inline uint32_t edu_dispatch(const struct edu_ops *ops, void *ctx, const void *req, uint32_t n,
                                    void *rep, handle_t *rhs, uint32_t *rhn)
{
    return edu_dispatch_on(HANDLE_INVALID, ops, ctx, req, n, rep, rhs, rhn);
}

/* Take the next message on ch into slot (idl_take), a slot with room for
 * the protocol's biggest request: ERR_INVALID_ARGS if it has less. */
static inline status_t edu_take_slot(handle_t ch, const struct idl_slot *slot)
{
    if (slot->qcap < EDU_REQ_MAX)
        return ERR_INVALID_ARGS;
    return idl_take(ch, slot);
}

/* Run the request in slot (taken by edu_take_slot, or found there by a
 * successor), which came on ch: as edu_dispatch_on, its reply built
 * in slot->r and the handles that reply carries put into rhs
 * (IDL_REP_HANDLES slots; *rhn of them). A request that carried handles is
 * answered ERR_INVALID_ARGS without its handler seeing it. Returns the
 * reply's length: 0 means no reply (no txid, or a `later` handler
 * answers it itself). No I/O; the caller sends the reply with the handles,
 * or closes them if it can't. */
static inline uint32_t edu_run_slot(handle_t ch, const struct idl_slot *slot,
                                    const struct edu_ops *ops, void *ctx, handle_t *rhs, uint32_t *rhn)
{
    *rhn = 0;
    if (*slot->n >= sizeof(uint32_t) && *slot->nh)
        return idl_refuse(slot);
    return edu_dispatch_on(ch, ops, ctx, slot->q, *slot->n, slot->r, rhs, rhn);
}

/* Is the method with this wire ordinal idempotent (its keyword in the
 * .idl): run again on the state its first run left, it gives the same
 * result and the same answer? A server that keeps nothing across a
 * restart may run such a request again; any other it answers with an
 * error. */
static inline bool edu_idempotent(uint32_t ordinal)
{
    (void)ordinal;
    return false;   /* no method is marked */
}

/* Take one message off ch and answer it. OK once a message was handled
 * (its reply may still have been dropped: the client is gone, or never
 * called); otherwise drv_channel_read's status: ERR_SHOULD_WAIT when
 * nothing is queued, ERR_PEER_CLOSED when the client is gone for good. */
static inline status_t edu_serve_one(handle_t ch, const struct edu_ops *ops, void *ctx)
{
    _Alignas(8) uint8_t idl_q[EDU_REQ_MAX];
    _Alignas(8) uint8_t idl_r[EDU_REP_MAX];
    handle_t idl_hs[IDL_READ_HANDLES];
    uint32_t idl_n = 0, idl_nh = 0;
    status_t idl_st = drv_channel_read(ch, idl_q, sizeof(idl_q), &idl_n, idl_hs, IDL_READ_HANDLES,
                                       &idl_nh);
    if (idl_st == ERR_BUFFER_TOO_SMALL)
        return idl_drain(ch, idl_n, idl_nh);
    if (idl_st != OK)
        return idl_st;
    if (idl_nh) {
        idl_close_all(idl_hs, idl_nh);
        idl_reply_status(ch, idl_q, idl_n, ERR_INVALID_ARGS);
        return OK;
    }
    handle_t idl_rhs[IDL_REP_HANDLES];
    uint32_t idl_rhn = 0;
    uint32_t idl_rn = edu_dispatch_on(ch, ops, ctx, idl_q, idl_n, idl_r, idl_rhs, &idl_rhn);
    if (!idl_rn || drv_channel_write(ch, idl_r, idl_rn, idl_rhs, idl_rhn) != OK)
        idl_close_all(idl_rhs, idl_rhn);   /* not sent: they're still ours */
    return OK;
}

/* Serve ch until the client closes it (OK), or a wait or read fails
 * (that status: ERR_CANCELED when the driver is being killed). Each reply
 * goes out in the system call that takes the next request
 * (idl_serve_next). */
static inline status_t edu_serve(handle_t ch, const struct edu_ops *ops, void *ctx)
{
    _Alignas(8) uint8_t idl_q[EDU_REQ_MAX];
    _Alignas(8) uint8_t idl_r[EDU_REP_MAX];
    handle_t idl_rhs[IDL_REP_HANDLES];
    struct idl_serve idl_s = {
        .ch = ch, .q = idl_q, .qcap = sizeof(idl_q), .r = idl_r, .rhs = idl_rhs,
    };
    for (;;) {
        status_t idl_st = idl_serve_next(&idl_s);
        if (idl_st == ERR_PEER_CLOSED)
            return OK;
        if (idl_st != OK)
            return idl_st;
        idl_s.rn = edu_dispatch_on(ch, ops, ctx, idl_q, idl_s.n, idl_r, idl_rhs, &idl_s.rhn);
    }
}
